fn checkpoint_internal(connection: &rusqlite::Connection, log_errors: bool) {
    if let Err(e) = connection.execute_batch("PRAGMA wal_checkpoint(TRUNCATE)") {
        if log_errors {
            warn!("wal_checkpoint failed: {e}");
